    /// Note that this may deadlock if not all locks have been released.
    #[verifier::exec_allows_no_decreases_clause]
    pub fn into_inner(self) -> (v: V)
        ensures
            self.inv(v),
    {
        let (v, _write_handle) = self.acquire_write();
        v
    }
}

