fn try_upgrade(            self) -> Result<RwLockWriteGuard<'a, T, G>, Self> {
    proof! {
        use_type_invariant(&self);
        use_type_invariant(self.inner);
        lemma_consts_properties();
    }
    let mut this = self;
    proof_decl! {
        let tracked mut upread_guard_token = this.tracked_token.get();
        let tracked mut write_perm: Option<PointsTo<T>> = None;
        let tracked mut err_upread_guard_token: Option<OneLeftOwner<HalfPerm<T>, NoPerm<T>, 3>> = None;
        let tracked mut retract_upgrade_token: Option<UniqueToken> = None;
        let tracked mut write_guard_token = None;
    }

    let res =
        atomic_with_ghost!(
        this.inner.lock => compare_exchange(UPGRADEABLE_READER | BEING_UPGRADED, WRITER | UPGRADEABLE_READER);
        update prev -> next;
         returning res;
         ghost g => {
             if res.is_ok() {
                 let tracked read_guard = match g.read_guard_token {
                     Sum::Left(token) => token,
                     Sum::Right(_) => proof_from_false(),
                 };
                 let tracked (read_perm, empty_read_guard) = read_guard.take_resource();
                 let tracked mut read_half = read_perm.0;
                 let tracked read_knowledge = read_perm.1;
                 g.read_guard_token = Sum::Right(empty_read_guard);

                 g.core_token.join_one_left_owner(upread_guard_token);
                 g.core_token.join_one_left_knowledge(read_knowledge);
                 let tracked mut core_half = g.core_token.take_resource_left();
                 core_half.combine(read_half);
                 let tracked (write_perm_value, empty_half) = core_half.take_resource();
